const lockRoomWorkspaceForWrite = `-- name: LockRoomWorkspaceForWrite :one
SELECT id FROM workspace WHERE id = $1 FOR KEY SHARE
`

// Room rows and their children have no foreign keys to workspace. Every Room
// transaction that can add graph data takes this shared lock before the Room
// row; workspace deletion takes FOR UPDATE before sweeping the graph.
func (q *Queries) LockRoomWorkspaceForWrite(ctx context.Context, workspaceID pgtype.UUID) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, lockRoomWorkspaceForWrite, workspaceID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

